@pytest.mark.parametrize("restore", [copy.deepcopy, pickle_roundtrip])
@pytest.mark.parametrize("kind", ["immutable", "lazy", "materialized_lazy"])
@pytest.mark.parametrize("whole_trace", [False, True])
def test_span_copy_roundtrip(live_span, restore, kind, whole_trace):
    live_span.end()
    span = live_span.to_immutable_span()
    if kind != "immutable":
        lazy = LazySpan.from_stored_content(json.dumps(span.to_dict()))
        if kind == "materialized_lazy":
            assert lazy.name == span.name
        lazy._attachments = span._attachments
        span = lazy

    original = (
        Trace(info=create_test_trace_info("tr-test"), data=TraceData(spans=[span]))
        if whole_trace
        else span
    )
    restored = restore(original)
    restored_span = restored.data.spans[0] if whole_trace else restored
    assert type(restored_span) is type(span)
    assert restored_span is not span
    if kind != "immutable":
        assert restored_span.__dict__["_materialized"] is False
        assert restored_span.__dict__["_raw_json"] is None
        assert "_span" not in restored_span.__dict__

    assert restored_span.to_dict() == span.to_dict()
    assert restored_span.name == span.name
    assert restored_span.inputs == span.inputs
    assert restored_span.outputs == span.outputs
    assert restored_span.events == span.events
    assert restored_span.links == span.links
    assert restored_span._attachments is not span._attachments
    for key, attachment in span._attachments.items():
        restored_attachment = restored_span._attachments[key]
        assert restored_attachment is not attachment
        assert restored_attachment.id == attachment.id
        assert restored_attachment.content_type == attachment.content_type
        assert restored_attachment.content_bytes == attachment.content_bytes


