    class AudioOutput(BaseModel):
        transcript: str
        audio: dict[str, str]

    audio_b64 = base64.b64encode(b"RIFF\x00\x00\x00\x00WAVEfmt ").decode()
    output = AudioOutput(
        transcript="Hello",
        audio={"data": audio_b64, "id": "audio_123"},
