tests/entities/test_span_copy.py
import copy
import json
import pickle

import pytest
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.trace import NonRecordingSpan

import mlflow
from mlflow.entities import LiveSpan, SpanEvent, Trace, TraceData
from mlflow.entities.link import Link
from mlflow.entities.span import LazySpan, NoOpSpan
from mlflow.tracing.attachments import Attachment

from tests.tracing.helper import create_test_trace_info


def pickle_roundtrip(value):
    return pickle.loads(pickle.dumps(value))


@pytest.fixture
def live_span():
    tracer = TracerProvider().get_tracer("test")
    span = LiveSpan(tracer.start_span("test"), trace_id="tr-test")
    span.set_inputs({"values": [1, 2]})
    span.set_outputs({"image": Attachment(content_type="image/png", content_bytes=b"image")})
    span.add_event(SpanEvent("event", timestamp=123, attributes={"key": "value"}))
    span.add_link(Link(trace_id="tr-" + "1" * 32, span_id="2" * 16, attributes={"key": "value"}))
    yield span
    if span._span.is_recording():
        span.end()


@pytest.mark.parametrize("restore", [copy.deepcopy, pickle_roundtrip])
@pytest.mark.parametrize("kind", ["immutable", "lazy", "materialized_lazy"])
@pytest.mark.parametrize("whole_trace", [False, True])
def test_span_copy_roundtrip(live_span, restore, kind, whole_trace):
    live_span.end()
    span = live_span.to_immutable_span()
    if kind != "immutable":
        lazy = LazySpan.from_stored_content(json.dumps(span.to_dict()))
        if kind == "materialized_lazy":
            assert lazy.name == span.name
        lazy._attachments = span._attachments
        span = lazy

    original = (
        Trace(info=create_test_trace_info("tr-test"), data=TraceData(spans=[span]))
        if whole_trace
        else span
    )
    restored = restore(original)
    restored_span = restored.data.spans[0] if whole_trace else restored
    assert type(restored_span) is type(span)
    assert restored_span is not span
    if kind != "immutable":
        assert restored_span.__dict__["_materialized"] is False
        assert restored_span.__dict__["_raw_json"] is None
        assert "_span" not in restored_span.__dict__

    assert restored_span.to_dict() == span.to_dict()
    assert restored_span.name == span.name
    assert restored_span.inputs == span.inputs
    assert restored_span.outputs == span.outputs
    assert restored_span.events == span.events
    assert restored_span.links == span.links
    assert restored_span._attachments is not span._attachments
    for key, attachment in span._attachments.items():
        restored_attachment = restored_span._attachments[key]
        assert restored_attachment is not attachment
        assert restored_attachment.id == attachment.id
        assert restored_attachment.content_type == attachment.content_type
        assert restored_attachment.content_bytes == attachment.content_bytes


@pytest.mark.parametrize("immutable", [False, True])
def test_span_shallow_copy(live_span, immutable):
    span = live_span.to_immutable_span() if immutable else live_span
    restored = copy.copy(span)
    assert restored is not span
    assert type(restored) is type(span)
    assert restored._span is span._span
    assert restored._attributes is span._attributes


@pytest.mark.parametrize(
    ("operation", "verb"), [(copy.deepcopy, "deepcopied"), (pickle.dumps, "pickled")]
)
def test_live_span_copy_rejected(live_span, operation, verb):
    with pytest.raises(TypeError) as exc:
        operation(live_span)
    assert str(exc.value) == (
        f"'LiveSpan' cannot be {verb} while active. Call `span.to_immutable_span()`"
    )


@pytest.mark.parametrize("restore", [copy.copy, copy.deepcopy, pickle_roundtrip])
@pytest.mark.parametrize("with_context", [False, True])
def test_noop_span_copy(live_span, restore, with_context):
    context = live_span._span.context if with_context else None
    span = NoOpSpan(NonRecordingSpan(context))
    restored = restore(span)
    assert isinstance(restored, NoOpSpan)
    assert restored is not span
    assert restored.trace_id == span.trace_id
    assert restored._span.get_span_context() == context
    restored.set_inputs({"value": 1})
    restored.end()


@pytest.mark.parametrize("restore", [copy.deepcopy, pickle_roundtrip])
def test_lazy_span_copy_does_not_materialize(live_span, restore):
    span = LazySpan.from_stored_content(json.dumps(live_span.to_immutable_span().to_dict()))
    restored = restore(span)
    assert span.__dict__["_materialized"] is False
    assert restored.__dict__["_materialized"] is False
    assert set(span.__getstate__()) == {"span_data", "attachments"}
    assert json.loads(restored.json_for_export()) == json.loads(span.json_for_export())
    assert restored.name == "test"
    assert restored.__dict__["_materialized"] is True


@pytest.mark.parametrize("restore", [copy.deepcopy, pickle_roundtrip])
@pytest.mark.parametrize("search", [False, True])
def test_fetched_trace_copy(restore, search):
    with mlflow.start_span("root") as span:
        span.set_inputs({"x": 1})
        with mlflow.start_span("child") as child:
            child.set_outputs({"y": 2})

    trace = (
        mlflow.search_traces(return_type="list")[0]
        if search
        else mlflow.get_trace(span.trace_id)
    )
    restored = restore(trace)
    assert restored.to_dict() == trace.to_dict()
    assert [s.name for s in restored.data.spans] == ["root", "child"]

